#!/usr/bin/env python3
"""
Round 123b (culprits), 2 October 2026. Needs round 122b.

Keyless satellite imagery, the two overlap ways to combine layers, raising
off by default, natural disasters, environmental law and investor suits as
data, water scarcity reordered with who causes it, mining split, land cover
moved, fire rows as asked, and the share of the map that is live.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

HEAD = "## Round 123b (2 October)"


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round123b: run from the culprits repository root")
    text = (root / "HANDOFF.md").read_text(encoding="utf-8")
    if "## Round 122b" not in text:
        sys.exit("round123b: round 122b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round123b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/index.html", "map/test.mjs", check=False)
            sys.exit("round123b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round123b: applied")
    h = root / "HANDOFF.md"
    text = h.read_text(encoding="utf-8")
    if HEAD not in text:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + NOTE + text[at:], encoding="utf-8")


NOTE = '## Round 123b (2 October)\n\nNeeds round 122b. Tiles patch round123b_tiles.py beside it. No app.js?v= bump.\n\n- Basemap: Esri\'s keyless imagery now answers "API key required" close in.\n  With ESRI_TOKEN empty, the imagery is EOX Sentinel-2 cloudless 2024 at every\n  zoom and the Esri hillshade an empty square (esri-hillshade-off://); a free\n  ArcGIS key in ESRI_TOKEN brings Esri back through ibasemaps-api.\n- Combine ticked layers: "Where they overlap the most" (overlap: layers\n  present within ~200 km, counted, two or more) and "Where their highest\n  values overlap" (peaks). LIFT_ON false by default; nothing turns on 3D.\n- Hologram blue shading off by default (opt.shade123 resets a saved on).\n- Natural disasters: kinds as h5 under Every kind together; plainer titles;\n  berkeley_warming (tiles berkeley_warming.py) replaces GFW\'s undrawn copy.\n- Environmental law: site_environment_law and enviro_law_by_country from\n  envlaw/ (tiles envlaw.py); _shapes removed; isds_tracker and ect_secrets\n  are country rows from UNCTAD\'s case list (tiles isds_unctad.py).\n- Water scarcity: jrc_water first (dataOnly remap: non-palette and faint\n  pixels left clear), aqueduct_proj, then Reservoirs, Water conflicts\n  (ejatlas_water, onlyGroup), Who causes water scarcity (water_culprits, tiles\n  water_culprits.py); aqueduct_crop removed; reservoirs with no usual area are\n  "no reading".\n- Mining: bundle split; pangaea_global_mining leads. Forest and land cover\n  rows under Land Use and Ecoregions; ESA and Indonesia land cover pinned to\n  finished tiles (GFW_FIXED); UMD land cover 2000-2020 out (no tiles).\n- Fire: inpe_fire_2023, Trase BURNED_PEAT and EMISSION_BURNED_PEAT_CO2, MODIS\n  active fires out; VIIRS bundle (3 months, with remains_fire inside); tree\n  cover lost to fire coloured by year (remap tcl_fire).\n- "% of the map is live" badge at the top (liveShareBadge).\n- Not done: development projects vanishing (not reproduced); MODIS burned\n  areas still on-request; named water culprits points.\n\n'
DIFF = ""

if __name__ == "__main__":
    main()
